        }) || '';

        // Check remote branches — direct remote query, no fetch needed
        const remoteBranches = runCmd({
            command: 'git ls-remote --heads origin "' + baseBranchName + '*"'
        }) || '';

        const allBranches = localBranches + '\n' + remoteBranches;

