        var specs = gitStaging.buildStagingPathspecs();
        for (var i = 0; i < ALL_ARTIFACTS.length; i++) {
            assert.contains(specs, '":!' + ALL_ARTIFACTS[i] + '"',
                'staging pathspec must exclude ' + ALL_ARTIFACTS[i]);
            assert.contains(specs, '":!' + ALL_ARTIFACTS[i] + '/**"',
                'staging pathspec must exclude ' + ALL_ARTIFACTS[i] + '/**');
