        if (prUrl) {
            comment += m.bold('Pull Request:') + ' ' + prUrl + '\n';
        } else {
            comment += m.bold('Pull Request:') + ' Created (check GitHub for URL)\n';
        }

        comment += '\nAI Teammate has completed the implementation and created a pull request for review.';

