        'ignored path ' + p + ' must not be named in the pathspec (guard)');
});
```

The inline ternary re-deriving the `.dmtools` prefix from the file name is hard to scan. Since `gitStaging.RUNTIME_ARTIFACT_PATHS` is exported and already drives the other assertions, iterate it directly:

```js
gitStaging.RUNTIME_ARTIFACT_PATHS.forEach(function (p) {
    assert.notContains(addCall, '":!' + p + '"',
        'ignored path ' + p + ' must not be named in the pathspec (guard)');
});
```

Same coverage, and it can never drift when the canonical list gains a new artifact.
